public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return res;
    }
    boolean[] used = new boolean[nums.length];
    backtrack(nums, used, new ArrayList<>(), res);
    return res;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> res) {
    if (current.size() == nums.length) {
        res.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, used, current, res);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Precompute substring sets for each string
    List<Set<String>> substringSets = new ArrayList<>(strings.size());
    for (String s : strings) {
        if (s == null) {
            return 0; // Treat null string as empty, thus no substrings
        }
        Set<String> set = new HashSet<>();
        int n = s.length();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                set.add(s.substring(i, j));
            }
        }
        substringSets.add(set);
    }

    // Generate candidate substrings from the first string
    String first = strings.get(0);
    int maxLen = 0;
    int len = first.length();
    for (int i = 0; i < len; i++) {
        for (int j = i + 1; j <= len; j++) {
            String candidate = first.substring(i, j);
            int candLen = j - i;
            if (candLen <= maxLen) { // already shorter or equal to best, skip
                continue;
            }
            String reverse = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;
            for (Set<String> set : substringSets) {
                if (!(set.contains(candidate) || set.contains(reverse))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                maxLen = candLen;
            }
        }
    }
    return maxLen;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;
    int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                // Start a new deposit
                deposits++;
                // BFS/DFS stack
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0], cc = pos[1];
                    for (int dir = 0; dir < 8; dir++) {
                        int nr = cr + dx[dir];
                        int nc = cc + dy[dir];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

