public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        // Basic validation
        if (n <= 0 || start == null || end == null || start.length == 0 || end.length == 0) {
            return "cannot be travelled";
        }

        // Assume the first element represents the unique node id
        int startNode = start[0];
        int endNode = end[0];

        if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
            return "cannot be travelled";
        }

        // Build adjacency list
        java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new java.util.ArrayList<>());
        }

        if (paths != null) {
            for (int[] p : paths) {
                if (p != null && p.length == 2) {
                    int u = p[0];
                    int v = p[1];
                    if (u >= 0 && u < n && v >= 0 && v < n) {
                        adj.get(u).add(v);
                        adj.get(v).add(u); // assuming undirected graph
                    }
                }
            }
        }

        // Breadth‑first search to check connectivity
        boolean[] visited = new boolean[n];
        java.util.Deque<Integer> queue = new java.util.ArrayDeque<>();
        queue.add(startNode);
        visited[startNode] = true;

        while (!queue.isEmpty()) {
            int current = queue.poll();
            if (current == endNode) {
                return "can be travelled";
            }
            for (int neighbor : adj.get(current)) {
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    queue.add(neighbor);
                }
            }
        }

        return "cannot be travelled";
    } catch (Exception e) {
        // Any exception is treated as an indication that travel is impossible
        return "cannot be travelled";
    }
}

