public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int maxK = n / 2;
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[maxK + 1];
    for (int i = 0; i <= maxK; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);
    for (int num : nums) {
        // iterate k from maxK down to 1
        for (int k = Math.min(maxK, n); k >= 1; k--) {
            java.util.HashSet<Integer> prevSet = dp[k - 1];
            if (!prevSet.isEmpty()) {
                java.util.Iterator<Integer> it = prevSet.iterator();
                while (it.hasNext()) {
                    int prevSum = it.next();
                    dp[k].add(prevSum + num);
                }
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((long) totalSum * k % n != 0L) {
            continue;
        }
        int target = (int) ((long) totalSum * k / n);
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    try {
        int n = cost.length;
        int prev = 0; // dp[0]
        int curr = 0; // dp[1]
        for (int i = 2; i <= n; i++) {
            int step1 = curr + cost[i - 1];
            int step2 = prev + cost[i - 2];
            int next = Math.min(step1, step2);
            prev = curr;
            curr = next;
        }
        return curr;
    } catch (Exception e) {
        // In case of unexpected errors, return 0 as a safe default
        return 0;
    }
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) {
        return 0;
    }
    // Morse code representations for letters 'a' to 'z'
    String[] morse = {
        ".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..", ".---",
        "-.-", ".-..", "--", "-.", "---", ".--.", "--.-", ".-.", "...", "-",
        "..-", "...-", ".--", "-..-", "-.--", "--.."
    };
    java.util.HashSet<String> set = new java.util.HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue; // skip null words
        }
        StringBuilder sb = new StringBuilder();
        for (char ch : word.toCharArray()) {
            if (ch >= 'a' && ch <= 'z') {
                sb.append(morse[ch - 'a']);
            } else if (ch >= 'A' && ch <= 'Z') {
                sb.append(morse[ch - 'A']);
            } else {
                // Ignore characters that are not letters
                continue;
            }
        }
        set.add(sb.toString());
    }
    return set.size();
}

public boolean hasAllCodes(String s, int k) {
    // Validate input
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (k > n) {
        return false;
    }
    // Prevent overflow: if k is too large, 2^k cannot be stored in int
    if (k >= 31) { // shift by 31 would overflow for int
        return false;
    }
    int totalComb = 1 << k;            // total possible binary strings of length k
    boolean[] seen = new boolean[totalComb];
    int count = 0;
    int mask = totalComb - 1;          // mask to keep only k bits
    int val = 0;                       // current k-bit window value

    for (int i = 0; i < n; i++) {
        // Build the current window value
        val = ((val << 1) & mask) | (s.charAt(i) - '0');

        // Once we have at least k characters processed
        if (i >= k - 1) {
            if (!seen[val]) {
                seen[val] = true;
                count++;
                // All combinations have been seen
                if (count == totalComb) {
                    return true;
                }
            }
        }
    }
    return false;
}

