public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    long currentMax = nums[0];
    long bestMax = nums[0];
    long currentMin = nums[0];
    long bestMin = nums[0];

    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        currentMax = Math.max(val, currentMax + val);
        bestMax = Math.max(bestMax, currentMax);

        currentMin = Math.min(val, currentMin + val);
        bestMin = Math.min(bestMin, currentMin);
    }

    long absMax = Math.max(Math.abs(bestMax), Math.abs(bestMin));
    return (int) absMax;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }
    // Generate Fibonacci numbers up to k
    java.util.List<Long> fibs = new java.util.ArrayList<>();
    fibs.add(1L); // F1
    fibs.add(1L); // F2
    while (true) {
        int size = fibs.size();
        long next = fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }

    int count = 0;
    long remaining = k;
    // Greedy subtraction using the largest Fibonacci <= remaining
    while (remaining > 0) {
        for (int i = fibs.size() - 1; i >= 0; i--) {
            long f = fibs.get(i);
            if (f <= remaining) {
                remaining -= f;
                count++;
                break; // start again from the largest Fibonacci
            }
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }
    java.util.Collections.sort(factors);
    return k <= factors.size() ? factors.get(k - 1) : -1;
}

