private void dfs(String s, int idx, java.util.Set<String> used, int[] max) {
    if (idx == s.length()) {
        max[0] = Math.max(max[0], used.size());
        return;
    }
    for (int end = idx + 1; end <= s.length(); end++) {
        String substr = s.substring(idx, end);
        if (!used.contains(substr)) {
            used.add(substr);
            dfs(s, end, used, max);
            used.remove(substr);
        }
    }
}

