public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int ones = 0;
    int twos = 0;
    for (int num : nums) {
        // Update bits that have appeared twice
        twos |= ones & num;
        // Toggle bits that have appeared once
        ones ^= num;
        // Remove bits that have appeared three times
        ones &= ~twos;
    }
    return ones;
}

