                continue;
            }

            if (num >= low) {
                steppingSet.add((int) num);
            }

            int lastDigit = (int) (num % 10);

            if (lastDigit > 0) {
                long child = num * 10 + (lastDigit - 1);
                if (child <= high) {
                    queue.offer(child);
                }
            }

            if (lastDigit < 9) {
                long child = num * 10 + (lastDigit + 1);
                if (child <= high) {
                    queue.offer(child);
                }
            }
        }
    }

    result.addAll(steppingSet);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long high = n / (factor * 10);
        long cur = (n / factor) % 10;
        long low = n % factor;
        count += high * factor;
        if (cur == 1) {
            count += low + 1;
        } else if (cur > 1) {
            count += factor;
        }
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A number is a power of two if it is positive and only one bit is set.
    // Handle non-positive input explicitly to avoid unexpected true for negative values.
    if (n <= 0) {
        return false;
    }
    // Using bitwise trick: n & (n - 1) will be zero only for powers of two.
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("num must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    if (n == 0) {
        return 0;
    }

    int[][] horizontal = new int[m][n];
    int[][] vertical = new int[m][n];
    int[][] diagonal = new int[m][n];
    int[][] antiDiagonal = new int[m][n];

    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horizontal[i][j] = (j > 0) ? horizontal[i][j - 1] + 1 : 1;
                vertical[i][j] = (i > 0) ? vertical[i - 1][j] + 1 : 1;
                diagonal[i][j] = (i > 0 && j > 0) ? diagonal[i - 1][j - 1] + 1 : 1;
                antiDiagonal[i][j] = (i > 0 && j < n - 1) ? antiDiagonal[i - 1][j + 1] + 1 : 1;

                int currentMax = Math.max(
                        Math.max(horizontal[i][j], vertical[i][j]),
                        Math.max(diagonal[i][j], antiDiagonal[i][j])
                );
                if (currentMax > maxLen) {
                    maxLen = currentMax;
                }
            } else {
                horizontal[i][j] = 0;
                vertical[i][j] = 0;
                diagonal[i][j] = 0;
                antiDiagonal[i][j] = 0;
            }
        }
    }

    return maxLen;
}

public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }
    // Determine sign and work with absolute value as long
    boolean negative = n < 0;
    long absValue = n < 0 ? -(long) n : n;
    String absStr = Long.toString(absValue);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    // Build reversed string with dots after every three digits
    for (int i = absStr.length() - 1; i >= 0; i--) {
        sb.append(absStr.charAt(i));
        count++;
        if (count == 3 && i > 0) {
            sb.append('.');
            count = 0;
        }
    }
    // Reverse to get the final string
    String result = sb.reverse().toString();
    // Prepend negative sign if needed
    if (negative) {
        result = "-" + result;
    }
    return result;
}

public static int squarePermutations(int[] A) {
    if (A == null) return 0;
    int n = A.length;
    if (n <= 1) return 1;

    // Sort array to help skip duplicate permutations
    java.util.Arrays.sort(A);

    // Precompute all perfect squares up to the maximum possible sum
    int maxVal = A[n - 1];
    int maxSum = maxVal + maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }

    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();

    java.util.function.IntUnaryOperator dfs = new java.util.function.IntUnaryOperator() {
        @Override public int applyAsInt(int prevIndexWithMask) {
            int mask = prevIndexWithMask & 0xFFFFFFFF;
            int prevIndex = (prevIndexWithMask >>> 32) - 1; // -1 represents no previous element

            if (mask == (1 << n) - 1) {
                return 1; // All elements placed
            }

            long key = ((long)(prevIndex + 1) << 32) | (mask & 0xFFFFFFFFL);
            Integer cached = memo.get(key);
            if (cached != null) return cached;

            int total = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue; // already used

                if (prevIndex != -1 && !isSquare[A[prevIndex] + A[i]]) continue; // sum not square

                // Skip duplicate values at the same recursion depth
                if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;

                total += applyAsInt(((long) i << 32) | ((mask | (1 << i)) & 0xFFFFFFFFL));
            }

            memo.put(key, total);
            return total;
        }
    };

    // Start recursion with prevIndex = -1 and mask = 0
    return dfs.applyAsInt(((long)(-1) << 32) | 0L);
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int maxArea = 0;
    int[] stack = new int[n];
    int top = -1;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && currentHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int startRow = Math.max(0, sum - n + 1);
        int endRow = Math.min(m - 1, sum);
        if (sum % 2 == 0) { // even sum: traverse from bottom to top
            for (int i = endRow; i >= startRow; i--) {
                int j = sum - i;
                result[index++] = mat[i][j];
            }
        } else { // odd sum: traverse from top to bottom
            for (int i = startRow; i <= endRow; i++) {
                int j = sum - i;
                result[index++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    // Only positive integers allowed; otherwise return -1
    if (n <= 0) {
        return -1;
    }

    // Convert the integer to a character array of its digits
    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    // Find the longest non-increasing suffix
    int pivot = -1;
    for (int i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            pivot = i;
            break;
        }
    }

    // If no pivot, digits are in non-increasing order – no greater permutation
    if (pivot == -1) {
        return -1;
    }

    // Find the rightmost successor to the pivot in the suffix
    int successor = -1;
    for (int i = len - 1; i > pivot; i--) {
        if (digits[i] > digits[pivot]) {
            successor = i;
            break;
        }
    }

    // Swap pivot and successor
    char temp = digits[pivot];
    digits[pivot] = digits[successor];
    digits[successor] = temp;

    // Reverse the suffix starting at pivot + 1
    int left = pivot + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to an integer, handling overflow
    try {
        int result = Integer.parseInt(new String(digits));
        // Ensure the result is strictly greater than the original number
        if (result > n) {
            return result;
        } else {
            return -1;
        }
    } catch (NumberFormatException e) {
        // Integer overflow or invalid number
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new ArrayList<>();
    }
    return buildSymmetric(n);
}

private static List<String> buildSymmetric(int len) {
    if (len == 0) {
        return Arrays.asList("");
    }
    if (len == 1) {
        return Arrays.asList("0", "1", "8");
    }
    List<String> middle = buildSymmetric(len - 2);
    List<String> result = new ArrayList<>();
    char[][] pairs = { {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'} };
    for (String mid : middle) {
        for (char[] p : pairs) {
            result.add("" + p[0] + mid + p[1]);
        }
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length < 2) {
            return false;
        }
    }
    // Check for duplicate points
    if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
        (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
        (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    long crossProduct = (long)(x2 - x1) * (y3 - y1) - (long)(y2 - y1) * (x3 - x1);
    return crossProduct != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return -1; // invalid input
    }
    int[] dp = new int[n];
    dp[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    long next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        long nextUgly = Math.min(Math.min(next2, next3), next5);
        dp[i] = (int) nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = (long) dp[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = (long) dp[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = (long) dp[i5] * 5;
        }
    }
    return dp[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    char prev = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == prev) {
            currentLen++;
        } else {
            prev = c;
            currentLen = 1;
        }
        if (currentLen > maxLen) {
            maxLen = currentLen;
        }
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) return result;
    int curr = 1;
    for (int i = 1; i <= n; i++) {
        result.add(curr);
        if ((long) curr * 10 <= n) {
            curr *= 10;
        } else {
            while (curr % 10 == 9 || curr + 1 > n) {
                curr /= 10;
            }
            curr++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int n : nums) {
        freq.put(n, freq.getOrDefault(n, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int sqrt = (int) Math.sqrt(n);
    if (sqrt * sqrt == n) {
        return 1;
    }
    for (int i = 1; i <= sqrt; i++) {
        int rem = n - i * i;
        int sqrtRem = (int) Math.sqrt(rem);
        if (sqrtRem * sqrtRem == rem) {
            return 2;
        }
    }
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 == 7) {
        return 4;
    }
    return 3;
}

public static String reverseWords(String s) {
    // Handle null input gracefully
    if (s == null) {
        return null;
    }

    char[] chars = s.toCharArray();
    int n = chars.length;
    int i = 0;

    while (i < n) {
        // Skip any spaces
        if (chars[i] == ' ') {
            i++;
            continue;
        }

        // Find the start and end of the current word
        int start = i;
        while (i < n && chars[i] != ' ') {
            i++;
        }
        int end = i - 1;

        // Reverse the characters of this word in place
        while (start < end) {
            char temp = chars[start];
            chars[start] = chars[end];
            chars[end] = temp;
            start++;
            end--;
        }
    }

    return new String(chars);
}
